 "Platina de la prensa": "Druckplatte der Presse",
 "<div style=\"display:flex;gap:18px;align-items:center\"><span style=\"flex:0 0 52px;height:52px;border-radius:26px;background:#b0201c;color:#fff;font-weight:700;text-align:center;line-height:52px;font-size:28px\">1</span><span><b style=\"font-family:'Playfair Display', serif;font-size:28px\">Fundir los tipos</b><br><span style=\"color:#6b6b6b\">Metal fundido en moldes, letra a letra</span></span></div>": "<div style=\"display:flex;gap:18px;align-items:center\"><span style=\"flex:0 0 52px;height:52px;border-radius:26px;background:#b0201c;color:#fff;font-weight:700;text-align:center;line-height:52px;font-size:28px\">1</span><span><b style=\"font-family:'Playfair Display', serif;font-size:28px\">Lettern gießen</b><br><span style=\"color:#6b6b6b\">Geschmolzenes Metall in Formen, Buchstabe für Buchstabe</span></span></div>",
 "<div style=\"display:flex;gap:18px;align-items:center\"><span style=\"flex:0 0 52px;height:52px;border-radius:26px;background:#b0201c;color:#fff;font-weight:700;text-align:center;line-height:52px;font-size:28px\">2</span><span><b style=\"font-family:'Playfair Display', serif;font-size:28px\">Componer</b><br><span style=\"color:#6b6b6b\">Ordenar los tipos en líneas y páginas</span></span></div>": "<div style=\"display:flex;gap:18px;align-items:center\"><span style=\"flex:0 0 52px;height:52px;border-radius:26px;background:#b0201c;color:#fff;font-weight:700;text-align:center;line-height:52px;font-size:28px\">2</span><span><b style=\"font-family:'Playfair Display', serif;font-size:28px\">Setzen</b><br><span style=\"color:#6b6b6b\">Die Lettern zu Zeilen und Seiten ordnen</span></span></div>",
